// Dibuja el icono 48x48 aplicando el color deseado (RGB565) sobre el framebuffer
inline void draw(int x, int y, const uint8_t *bitmap, uint16_t color, uint8_t alpha = 255) {
    for (int j = 0; j < 48; j++) {
        for (int i = 0; i < 48; i++) {
            int byteIdx = j * 6 + (i / 8);
            int bit = 7 - (i % 8);
            if (pgm_read_byte(&bitmap[byteIdx]) & (1 << bit)) {
                Fb::blendPixel(x + i, y + j, color, alpha);
            }
        }
    }
}

